    "en": "I don't feel comfortable with this kind of event, but my hobby is...",
    "note": "The source has the conversationally awkward あまりこういう席は苦手. A regular version is こういう席はあまり得意ではない, “I am not very comfortable at events like this.” あまり commonly accompanies a negative in this degree meaning; it can have other uses, so it is not always followed by ない. 席 here means an occasion or gathering.",
